-- 021_zastosowania_wozek_tylko_przemyslowe.sql — ticket 185-FEATURE-przypisanie-kategorii-zastosowania
--
-- ŚWIADOME ODSTĘPSTWO OD PRODUKCJI (decyzja użytkownika, 2026-10-04): „Wózek widłowy" jest zastosowaniem
-- WYŁĄCZNIE kategorii Przemysłowe. Z listy dozwolonych dla Rolniczych wypada — zapis „Rolnicze / Wózek
-- widłowy" trigger zamienia teraz na „Rolnicze / Uniwersalne/pozostałe" (jak każde inne zastosowanie spoza
-- listy). Dotychczasowe 22 produkty z tą parą przenosi skrypt `przypisz-kategorie-zastosowanie`
-- (Rolnicze → Przemysłowe), nie ta migracja: migracja NIE rusza istniejących wierszy.
--
-- Treść triggerów `products_zastosowanie_ai` / `_au` = dosłownie ta z 011 (kopia 7d6cfc9:db/schema.sql),
-- z JEDNĄ różnicą: w gałęzi kategorii `Rolnicze` usunięto dwa warunki mapujące `wózek widłowy` na
-- `Wózek widłowy` (gałąź Przemysłowe zostaje bez zmian). Pozostałe cztery triggery z 011 (blokady
-- płatności, kanoniczna kategoria poprawek) nietknięte. Odporna na istniejące obiekty: DROP IF EXISTS + CREATE.
-- Plik `legacy/application_rules.cjs` (bajt-w-bajt kopia produkcji) zostaje bez zmian — nie jest ładowany
-- w czasie działania, a parsery nie wypełniają zastosowania z plików dostawców.

DROP TRIGGER IF EXISTS products_zastosowanie_ai;
DROP TRIGGER IF EXISTS products_zastosowanie_au;

CREATE TRIGGER products_zastosowanie_ai
      AFTER INSERT ON products
      BEGIN
        UPDATE products
        SET kategoria = CASE WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('rolnicze') THEN 'Rolnicze' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('rolnicza') THEN 'Rolnicze' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('przemyslowe') THEN 'Przemysłowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('przemysłowe') THEN 'Przemysłowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('przemyslowa') THEN 'Przemysłowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('przemysłowa') THEN 'Przemysłowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('ciezarowe') THEN 'Ciężarowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('ciężarowe') THEN 'Ciężarowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('ciezarowa') THEN 'Ciężarowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('ciężarowa') THEN 'Ciężarowe' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('lesne') THEN 'Leśne' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('leśne') THEN 'Leśne' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('lesna') THEN 'Leśne' WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('leśna') THEN 'Leśne' ELSE TRIM(NEW.kategoria) END,
            zastosowanie = CASE
              WHEN NEW.zastosowanie IS NULL OR TRIM(NEW.zastosowanie) = '' THEN NEW.zastosowanie
              ELSE CASE WHEN NEW.zastosowanie IS NULL OR TRIM(NEW.zastosowanie) = '' THEN NULL WHEN LOWER(TRIM(NEW.kategoria)) = LOWER('Rolnicze') THEN CASE WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('ciągnik') THEN 'Ciągnik' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('ciągnik leśny') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('kombajn') THEN 'Kombajn' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('opryskiwacz') THEN 'Opryskiwacz' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('przyczepa') THEN 'Przyczepa' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('przyczepa / flotacja') THEN 'Przyczepa' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('przyczepa/flotacja') THEN 'Przyczepa' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('przyczepa leśna') THEN 'Przyczepa' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('ładowarka') THEN 'Ciągnik' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('ładowarka kołowa') THEN 'Ciągnik' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('ładowarka rolnicza') THEN 'Ciągnik' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('kosiarka') THEN 'Kosiarka/ogród' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('kosiarka/ogród') THEN 'Kosiarka/ogród' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('koparka') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('kompaktor') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('kompaktor/walec') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('suwnica/dźwig') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('suwnice/dźwig') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('maszyny górnicze') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('maszyny górnicze/kamieniołomy') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('maszyny górnicze/kamieniołomy (otr)') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('all position') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('all-position') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('oś kierowana') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('oś napędowa') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('naczepa') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('naczepa/przyczepa') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('harwester') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('forwarder') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('skidder') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('skider') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('rolnicze (ogólne)') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('przemysłowe (ogólne)') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('ciężarowe (ogólne)') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('leśne (ogólne)') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('uniwersalne') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('uniwersalne/pozostałe') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('uniwersalne przemysłowe') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('uniwersalne leśne') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('implement rolniczy') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('Ciągnik') THEN 'Ciągnik' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('Ciągnik leśny') THEN 'Uniwersalne/pozostałe' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('Kombajn') THEN 'Kombajn' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('Opryskiwacz') THEN 'Opryskiwacz' WHEN LOWER(TRIM(NEW.zastosowanie)) = LOWER('Przyczepa') THEN 'Przyczepa' WHEN 